const linhas = $input.all().map((i) => i.json);

// Mesma normalizacao de app/src/lib/whatsapp.ts (buildWhatsAppUrl) --
// tem que ficar identica nos dois lugares, senao o app pode mostrar o
// botao habilitado (tem_whatsapp=true) mas falhar ao montar o link de
// verdade no clique.
// 12/13 digitos = ja tem DDI; 10/11 = DDD+numero, prefixa 55; 8/9 =
// numero local SEM DDD (achado 12/08/2026 verificando telefone real
// de cliente -- cadastro antigo nao salvava DDD), prefixa DDD padrao
// + 55; resto = formato nao reconhecido, fica tem_whatsapp NULL.
const DDD_PADRAO = '85'; // Fortaleza, onde a farmacia fica -- confirmado com o usuario
function normalizarNumero(foneBruto) {
  const digits = String(foneBruto ?? '').replace(/\D/g, '');
  if (digits.length === 12 || digits.length === 13) return digits;
  if (digits.length === 10 || digits.length === 11) return `55${digits}`;
  if (digits.length === 8 || digits.length === 9) return `55${DDD_PADRAO}${digits}`;
  return null;
}

// numero normalizado -> lista de codigo_cliente (mais de um cliente
// pode compartilhar o mesmo telefone -- ex.: familia. Todos recebem o
// mesmo resultado da checagem, ninguem fica de fora por causa disso).
const mapa = {};
for (const linha of linhas) {
  const numero = normalizarNumero(linha.fone);
  if (!numero) continue;
  (mapa[numero] = mapa[numero] || []).push(linha.codigo);
}
const numbers = Object.keys(mapa); // ja deduplicado (chave do objeto)

return [{ json: { numbers, mapa, quantidade: numbers.length } }];

// [12/08/2026] Confirmado em producao (n8n 2.32.7): o HTTP Request
// node separa a resposta da Evolution API em UM ITEM POR NUMERO
// (cada item.json = {jid, exists, number}), nao um item so com
// {numbers: [...]} como a documentacao da Evolution API sugeria --
// por isso $input.all(), nao $input.first().
const itens = $input.all().map((i) => i.json);
const mapa = $('Montar lista de números').first().json.mapa;

function limparDigitos(numero) {
  return String(numero ?? '').replace(/\D/g, '');
}

const atualizacoes = [];
for (const item of itens) {
  // "number" ja vem sem o sufixo "@s.whatsapp.net" do jid -- limparDigitos
  // e so uma garantia extra, nao estritamente necessaria pro "number".
  const numeroLimpo = limparDigitos(item.number ?? item.jid ?? '');
  const codigos = mapa[numeroLimpo];
  if (!codigos) continue; // resposta nao bateu com nenhum numero que mandamos
  for (const codigo of codigos) atualizacoes.push({ codigo, existe: !!item.exists });
}

function pgVal(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  return String(Number(v));
}

let sql = 'SELECT 1';
if (atualizacoes.length > 0) {
  const valores = atualizacoes.map((a) => `(${pgVal(a.codigo)}, ${pgVal(a.existe)})`).join(',\n');
  sql = `UPDATE clientes SET tem_whatsapp = c.tem_whatsapp
FROM (VALUES ${valores}) AS c(codigo, tem_whatsapp)
WHERE clientes.tenant_id = '9b8b94ea-c072-4ab3-a8a5-d872f10c3b57' AND clientes.codigo = c.codigo;`;
}

return [{ json: { sql, qtdAtualizados: atualizacoes.length } }];
